#!/usr/bin/env bash
# Question 4: Document and use a custom field. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/crd
mkdir -p /opt/course/crd
chown -R ubuntu:ubuntu /opt/course
token="cka-$(head -c 4 /dev/urandom | od -An -tx1 | tr -d " \n")"
echo "$token" > /root/.cka-crd-token
kubectl delete crd databases.db.example.lab --ignore-not-found --wait=true >/dev/null
kubectl apply -f - <<EOF >/dev/null
apiVersion: apiextensions.k8s.io/v1
kind: CustomResourceDefinition
metadata:
  name: databases.db.example.lab
spec:
  group: db.example.lab
  scope: Namespaced
  names:
    plural: databases
    singular: database
    kind: Database
  versions:
    - name: v1
      served: true
      storage: true
      schema:
        openAPIV3Schema:
          type: object
          properties:
            spec:
              type: object
              properties:
                replicas:
                  type: integer
                  description: Number of database instances.
                backup:
                  type: object
                  description: When and where the operator takes backups.
                  properties:
                    schedule:
                      type: string
                      description: Cron schedule of the backups. Lab reference $token.
                    retention:
                      type: integer
                      description: How many backups to keep.
EOF
kubectl wait --for=condition=Established crd/databases.db.example.lab --timeout=60s >/dev/null
: "${Q4_NS}"
